class {
  onCreate(input) {
    if (typeof window === 'undefined' && input.request && input.response) {
      const url = new URL(input.request.url);
      const key = url.searchParams.get('key');

      if (key !== 'letmein') {
        input.response.statusCode = 401;
        input.response.setHeader('content-type', 'text/plain');
        input.response.end('unauthorized');
      }
    }
  }
}

<${input.renderBody}/>

export default function middleware(input) {
  const url = new URL(input.request.url, 'http://localhost');
  const key = url.searchParams.get('key');

  if (key !== 'letmein') {
    input.response.statusCode = 401;
    input.response.setHeader('content-type', 'text/plain');
    input.response.end('unauthorized');
    return;
  }
}

export async function onRequest(context) {
  const url = new URL(context.request.url);
  const key = url.searchParams.get('key');

  if (key !== 'letmein') {
    return new Response('unauthorized', { status: 401 });
  }
}

export default async function middleware(context) {
  const url = new URL(context.request.url);
  const key = url.searchParams.get('key');

  if (key !== 'letmein') {
    return new Response('unauthorized', { status: 401 });
  }
}

$ {
  let activeIndex = 0;
}

<div>
  <div role="tablist">
    <for|tab, i| of=input.tab>
      <button
        aria-selected=(i === activeIndex ? "true" : undefined)
        on-click() {
          activeIndex = i;
        }
      >
        ${tab.label}
      </button>
    </for>
  </div>

  <div id="panel">
    ${input.tab[activeIndex]?.renderBody()}
  </div>

  <@slot name="tab" label />
</div>

