export const params = {
  id: String,
};

export const GET = async ({ params }) => {
  const product = getProduct(params.id);

  if (!product) {
    return {
      status: 404,
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ error: "not found" }),
    };
  }

  return {
    status: 200,
    headers: { "content-type": "application/json" },
    body: JSON.stringify(product),
  };
};

