import { addEntry } from "../../store.js";

export async function post(req) {
  const formData = await req.formData();
  const message = formData.get("message");

  if (message && message.trim()) {
    addEntry(message.trim());
  }

  return new Response(null, {
    status: 303,
    headers: {
      "Location": "/guestbook"
    }
  });
}

